INSERT INTO notifications (id, title, content, type_id, target, target_value, scheduled_at, is_sent, created_by, created_at) VALUES
('TB-01112025-0001', 'Khẩn cấp: Sự cố thang máy', 'Thang máy tòa B tạm ngưng hoạt động để khắc phục sự cố. Dự kiến hoàn thành trong 2-3 giờ.', 1, 'Tất cả Cư dân', NULL, '2025-11-01 15:21:15', 1, 'ID0001', '2025-09-18 10:47:31'),
('TB-10122025-0001', 'Khai trương dịch vụ mới', 'Chúc mừng khai trương dịch vụ Phòng Gym tại tòa nhà. Ưu đãi 20% cho cư dân trong tháng đầu!', 4, 'Theo tòa nhà', 'A', '2025-12-10 08:50:08', 1, 'ID0001', '2025-10-18 05:32:32'),
('TB-21122025-0001', 'Phun thuốc diệt muỗi', 'Tòa nhà sẽ tiến hành phun thuốc diệt muỗi vào sáng thứ 7 tuần này. Vui lòng đóng cửa sổ.', 2, 'Theo tòa nhà', 'A', '2025-12-21 03:34:38', 1, 'ID0001', '2025-12-17 12:39:26'),
('TB-20112025-0001', 'Khẩn cấp: Sự cố thang máy', 'Thang máy tòa A tạm ngưng hoạt động để khắc phục sự cố. Dự kiến hoàn thành trong 2-3 giờ.', 1, 'Theo tòa nhà', 'A', '2025-11-20 06:01:43', 1, 'ID0001', '2025-10-21 21:04:38'),
('TB-04122025-0001', 'Phun thuốc diệt muỗi', 'Tòa nhà sẽ tiến hành phun thuốc diệt muỗi vào sáng thứ 7 tuần này. Vui lòng đóng cửa sổ.', 2, 'Theo tòa nhà', 'B', '2025-12-04 01:42:52', 1, 'ID0001', '2025-07-30 14:23:10'),
('TB-06012026-0001', 'Phun thuốc diệt muỗi', 'Tòa nhà sẽ tiến hành phun thuốc diệt muỗi vào sáng thứ 7 tuần này. Vui lòng đóng cửa sổ.', 2, 'Cá nhân', 'R0624', '2026-01-06 14:03:28', 0, 'ID0001', '2025-10-04 02:48:57'),
