INSERT INTO fund_campaigns (id, title, description, start_date, end_date, target_amount, current_amount, status, created_by) VALUES
(1, 'Quỹ Vui Hội Trăng Rằm 2024', 'Tổ chức chương trình Trung thu cho trẻ em trong tòa nhà. Quỹ sẽ được dùng để mua đèn lồng, bánh kẹo và tổ chức các trò chơi vui nhộn.', '2024-08-01', '2024-09-01', 20000000, 25500000, 'Closed', 'ID0002'),
(2, 'Quỹ Khuyến Học 2025', 'Hỗ trợ học bổng cho con em cư dân có hoàn cảnh khó khăn, học giỏi. Mỗi suất học bổng 5 triệu đồng.', '2025-01-01', '2025-12-31', 50000000, 18750000, 'Active', 'ID0002'),
(3, 'Quỹ Tết Sum Vầy 2026', 'Tổ chức chương trình Tết cộng đồng, trao quà cho người cao tuổi và trẻ em. Dự kiến tổ chức tại Hội trường tầng 1.', '2026-01-01', '2026-02-01', 100000000, 0, 'Planned', 'ID0002');
